import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, mul, add, sub, sin, cos, time, vec3 } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry – thin rule (adjust size as needed)
  const geometry = new PlaneGeometry(1.5, 0.2, 64, 64);
  const material = new MeshStandardNodeMaterial();
  material.roughness = 0.6;
  material.metalness = 0.3;
  material.clearcoat = 0.1;

  // Load textures (async, but function stays sync)
  const colorTexPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const depthTexPromise = ctx.textureLoader.loadTexture(config.depthMapUrl);

  // Apply textures when ready
  colorTexPromise.then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
    resources.colorTex = tex;
  });
  depthTexPromise.then((tex) => {
    // Displacement node using TSL
    const dispNode = mul(texture(tex, uv), 0.08);
    material.displacementNode = dispNode;
    material.needsUpdate = true;
    resources.depthTex = tex;
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Apply config transforms (position handled by adapter)
  if (config.rotation) root.rotation.set(...config.rotation);
  if (config.scale) root.scale.set(...config.scale);

  // Event handlers storage
  const handlers = {};
  root.userData.handlers = handlers;

  // GSAP timelines storage for cleanup
  const timelines = [];

  // Hover effect – rise-in (subtle, 0.15 units)
  handlers.hover = () => {
    const tl = gsap.timeline();
    tl.to(mesh.position, {
      y: mesh.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };
  // Hover leave – revert
  handlers.hoverLeave = () => {
    const tl = gsap.timeline();
    tl.to(mesh.position, {
      y: mesh.position.y - 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };

  // Click effect – emit navigation event
  handlers.click = () => {
    ctx.emit('hub-features.select', {});
  };

  // Apply cinematic primitives if any (including required parallax)
  const primitiveInstances = [];
  const primitivesList = config.cinematicPrimitives || [];
  // Ensure parallax-scroll is present
  const hasParallax = primitivesList.some((p) => p.name === 'parallax-scroll');
  if (!hasParallax) {
    primitivesList.push({ name: 'parallax-scroll', params: {}, trigger: 'load' });
  }
  for (const p of primitivesList) {
    const instance = ctx.primitives[p.name](root, p.params);
    primitiveInstances.push(instance);
  }

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();
    // Dispose textures if loaded
    if (resources.colorTex) resources.colorTex.dispose();
    if (resources.depthTex) resources.depthTex.dispose();
    // Kill GSAP timelines
    timelines.forEach((t) => t.kill());
    // Cleanup primitives
    primitiveInstances.forEach((inst) => {
      if (inst && typeof inst.cleanup === 'function') inst.cleanup();
    });
  };

  // Resource holder for cleanup
  const resources = {
    colorTex: null,
    depthTex: null,
  };

  return root;
}
